p="/assets/conversation-C4zUzv1Z.png",xp="/assets/detail-S-bFKDlb.png",Cp="/assets/applications-list-CGqqx3gX.png",_p="/assets/checklist-f9UgruQx.png",Np="/assets/pet-form-oGrHJeoU.png",Pp="/assets/invite-JMNHhj7E.png",Lp="/assets/whats-included-CMPJrbGx.png",Tp="/assets/applications-zaMme3Yu.png",zp="/assets/welcome-Cc3XDnD8.png",Rp="/assets/conversation-NvQW5UvX.png",Mp="/assets/address-search-4LRkaiZe.png",jp="/assets/rentspree-DrUF8uXp.png",Op="/assets/opendoor-DkIqXeLF.png",Dp="/assets/raytheon-BpI5rkAS.png",Ip="/assets/hudson-rouge-D5-uJ1Dv.png",Fp="/assets/code-and-theory-HZX48eXv.png",$p="/assets/profile-D2noHD0V.jpg",Ap=[{id:"applicant-experience",slug:"applicant-experience",title:"Applicant experience",disciplines:["Mobile UX","Information architecture","Content design"],headline:"Making a high-friction application feel finishable",body:["Applying for a rental is long, sensitive, mostly completed on a phone, and ends with a payment. The existing experience felt like one continuous wall of questions with little context about what was left or why information was being requested.","I restructured the application into clear chapters that follow the applicant’s mental model, created natural save and resume points, and rewrote the experience to explain sensitive asks as they happen. The result is a flow designed around confidence and momentum instead of simply getting applicants through more screens."],backgroundColor:"#FAF7F3",textColor:"#141414",layout:"panel",media:[{id:"applicant-list",label:"Applications list (mobile)",treatment:"phone",src:Cp,width:786,height:762},{id:"applicant-checklist",label:"Application checklist",treatment:"card",src:_p,width:786,height:762},{id:"applicant-pet-form",label:"Household details — pets",treatment:"card",src:Np,width:786,height:762}]},{id:"requesting-an-application",slug:"requesting-an-application",title:"Requesting an application",disciplines:[],headline:"",body:["Agents often send the same screening package again and again, but the old flow made them repeat the same multi-step setup every time.","I collapsed the common path to a few taps: choose the property, invite renters, done. The package stays preselected across properties, while deeper controls sit one tap behind “What’s included” for agents who need to customize or stage reports over time.","Once requests are out, the applications view makes progress easy to scan, with clear states for each applicant and grouped households for co-applicants and guarantors."],backgroundColor:"#F2E6FB",textColor:"#141414",layout:"open",media:[{id:"request-invite",label:"Invite your first applicant",treatment:"card",src:Pp,width:786,height:762},{id:"request-whats-included",label:"What’s included — application package",treatment:"card",src:Lp,width:786,height:762},{id:"request-applications",label:"Applications in progress",treatment:"card",src:Tp,width:786,height:762}]},{id:"messaging",slug:"messaging",title:"Messaging",disciplines:["Platform design","Responsive systems","Cross-product architecture"],headline:"Turning messaging into part of the rental workflow",body:["RentSpree connects agents, landlords, and applicants, but the conversation lived in personal texts and email, disconnected from the property and application.","I designed the messaging platform around that missing context: a responsive three-column hub where every conversation is tied to a property, its participants, and application activity. The foundation was built to support future milestones, templates, notifications, and automated workflows without redesigning the core experience."],backgroundColor:"#222222",textColor:"#F5F4F1",layout:"bleed",media:[{id:"messaging-list",label:"Messages list",treatment:"card",src:Sp,width:786,height:762},{id:"messaging-conversation",label:"Conversation hub (desktop)",treatment:"desktop",src:Ep,width:786,height:762},{id:"messaging-detail",label:"Messages (mobile)",treatment:"phone",src:xp,width:786,height:762}]},{id:"ai-assistant",slug:"ai-assistant",title:"Rental Assistant",disciplines:["AI product design","Conversational UX","Product analytics"],headline:"Finding the right role for AI in a complex workflow",body:["Screening an applicant or listing a property meant learning RentSpree’s navigation before getting anything done. I designed a conversational layer that lets agents start those jobs directly.","The workflows themselves worked: 79% of people who started creating an ApplyLink finished one, while 514 reviewed conversations produced zero compliance failures. But adoption exposed a more interesting problem. After reviewing all 1,083 sessions, I found that more than half of users disappeared when we asked for a property address.","The next iteration is in the works."],backgroundColor:"#FFFFFF",textColor:"#141414",layout:"open",media:[{id:"assistant-welcome",label:"Assistant welcome",treatment:"card",src:zp,width:786,height:762},{id:"assistant-conversation",label:"Assistant conversation",treatment:"card",src:Rp,width:786,height:762},{id:"assistant-address-search",label:"Assistant address search",treatment:"card",src:Mp,width:786,height:762}]},{id:"resume",slug:"resume",title:"Resume",backgroundColor:"#FFFFFF",textColor:"#141414",layout:"resume",workHistory:[{id:"rentspree",company:"Rentspree",role:"Sr. Staff Product Designer",logo:jp,dateRange:"Mar 2025 - Present",location:"New York, NY"},{id:"opendoor",company:"Opendoor",role:"Staff Product Designer",logo:Op,dateRange:"Feb 2022 - Dec 2024",location:"New York, NY"},{id:"raytheon",company:"Raytheon Technologies",role:"Product Design Manager",logo:Dp,dateRange:"Sept 2018 - Jan 2022",location:"Brooklyn, NY"},{id:"hudson-rouge",company:"Hudson Rouge",role:"Design Director",logo:Ip,dateRange:"Apr 2017 - Sept 2018",location:"New York, NY"},{id:"code-and-theory",company:"Code & Theory",role:"Senior Product Designer",logo:Fp,dateRange:"Feb 2013 - Mar 2017",location:"NYC, New York"}],contact:{photo:$p,email:"micahmicahdesign@gmail.com",linkedin:"https://www.linkedin.com/in/micahburger/",store:"https://cornerbodega.pub/",storeLabel:"store [taking a break]"}}];function Up(){return k.jsxs(k.Fragment,{children:[k.jsx(kp,{projects:Ap}),k.jsx(Zd,{})]})}bl.createRoot(document.getElementById("root")).render(k.jsx(Ic.StrictMode,{children:k.jsx(Up,{})}));
